INSERT INTO teacher(full_name,email,qualification) VALUES('Ananya Rao','ananya.rao@school.test','M.Sc Mathematics'),('Rahul Nair','rahul.nair@school.test','M.Sc Physics') ON CONFLICT(email) DO NOTHING;
INSERT INTO class(class_name,section,academic_year,room_number,class_teacher_id) SELECT '10','A','2026-2027','A-101',teacher_id FROM teacher WHERE email='ananya.rao@school.test' ON CONFLICT(class_name,section,academic_year) DO NOTHING;
INSERT INTO subject(subject_name,subject_code) VALUES('Mathematics','MATH10'),('Physics','PHY10') ON CONFLICT(subject_code) DO NOTHING;
INSERT INTO student(admission_no,first_name,last_name,date_of_birth,gender,email,class_id) SELECT 'ADM2026001','Aarav','Sharma','2010-04-12','Male','aarav@school.test',class_id FROM class WHERE class_name='10' AND section='A' AND academic_year='2026-2027' ON CONFLICT(admission_no) DO NOTHING;
INSERT INTO class_subject(class_id,subject_id,teacher_id,academic_year) SELECT c.class_id,s.subject_id,t.teacher_id,c.academic_year FROM class c CROSS JOIN subject s CROSS JOIN teacher t WHERE c.class_name='10' AND c.section='A' AND c.academic_year='2026-2027' AND ((s.subject_code='MATH10' AND t.email='ananya.rao@school.test') OR (s.subject_code='PHY10' AND t.email='rahul.nair@school.test')) ON CONFLICT(class_id,subject_id,academic_year) DO NOTHING;